insert into public.content_translations (entity, entity_id, locale, field, value) values
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','ca','title',$j$"La Ruta del Foc: exploració de la Fageda d'en Jordà i Castellfollit de la Roca"$j$::jsonb),
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','ca','area',$j$"La Garrotxa"$j$::jsonb),
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','ca','meeting_point',$j$"Estació del Nord, C/ d'Alí Bei 80, 08013 Barcelona (Metro L1 Arc de Triomf). Arribeu 15 minuts abans."$j$::jsonb),
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','ca','inclusions',$j$["Autocar d'anada i tornada des de Barcelona", "Guia acompanyant"]$j$::jsonb),
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','ca','exclusions',$j$["Menjar i begudes"]$j$::jsonb),
('tour','97c63004-427b-4de7-ae84-8a95425d56a8','ca','description',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🌋 Fageda d'en Jordà: un misteri geològic per al vostre grup", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "El faig de la Fageda d'en Jordà no és un bosc qualsevol; és una ", "type": "text"}, {"text": "zona d'exploració geològica única", "type": "text", "marks": [{"type": "bold"}]}, {"text": " assentada sobre una antiga colada de lava solidificada procedent del volcà Croscat. Situada a una altitud de 550 metres, representa un terreny inusual i poc freqüent a la península Ibèrica. Com a part de la comarca de la Garrotxa, estem envoltats per 21 cràters volcànics, una característica que inspira l'aventura i el descobriment. Aquest entorn ha estat font d'inspiració per a artistes i historiadors.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🔥 El Volcà de Santa Margarida: cohesió al cràter", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "En aquest impressionant entorn volcànic, destaquem el ", "type": "text"}, {"text": "volcà de Santa Margarida", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". La seva explosió va deixar un cràter ample i circular, en el qual hi ha una ermita romànica. Més enllà del prat que avui ocupa el cràter, la resta del volcà està coberta de boscos caducifolis. La nostra ruta d'exploració us portarà fins a l'Àrea de Santa Margarida (seguint part de l'itinerari 3), un tram ideal per fer ", "type": "text"}, {"text": "activitats de team building", "type": "text", "marks": [{"type": "bold"}]}, {"text": " i percebre la vertadera essència d'aquesta zona.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🧱 Castellfollit de la Roca: el baluard basàltic", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Situat a la vora d'un cingle de basalt de 50 metres d'altura i esculpit pel riu Fluvià, ", "type": "text"}, {"text": "Castellfollit de la Roca", "type": "text", "marks": [{"type": "bold"}]}, {"text": " és un dels pobles més petits i fascinants de la província de Girona. El poble s'assenta sobre dues colades de lava superposades que li donen una silueta dramàtica. El seu nucli antic, construït amb pedres volcàniques, ens remunta al segle XI i permet al nostre grup explorar la història des del carrer principal fins al mirador de Josep Pla. ", "type": "text"}, {"text": "És el final perfecte per a una jornada d'exploració geològica.", "type": "text", "marks": [{"type": "bold"}]}]}]}]}$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','ca','title',$j$"El Repte del Pirineu: exploració de Queralbs i la mítica Vall de Núria"$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','ca','area',$j$"Ripollès"$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','ca','difficulty',$j$"Mitjà (caminada opcional)"$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','ca','meeting_point',$j$"Estació del Nord, C/ d'Alí Bei 80, 08013 Barcelona (Metro L1 Arc de Triomf). Arribeu 15 minuts abans."$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','ca','inclusions',$j$["Autocar d'anada i tornada des de Barcelona", "Guia acompanyant", "Bitllet de cremallera d'anada i tornada", "Telecabina dins de la Vall de Núria"]$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','ca','exclusions',$j$["Menjar i begudes"]$j$::jsonb),
('tour','fd53a1d1-fcc4-4e2d-9f6c-8f951d8c8eaa','ca','description',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🏔️ Queralbs: el tresor de pedra del Pirineu", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "El nostre punt de partida és ", "type": "text"}, {"text": "Queralbs", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", un tresor històric situat a 1.220 metres d'altitud a la comarca del Ripollès. Amb cases de pedra de teulades de pissarra, Queralbs és un dels pobles més pintorescos del Pirineu català. Aquest poble, documentat històricament des de l'any 839, ofereix una mirada a la història local. Aquí explorarem el seu patrimoni, destacant l' ", "type": "text"}, {"text": "Església de Sant Jaume (s. X)", "type": "text", "marks": [{"type": "bold"}]}, {"text": " i el seu ajuntament, preparant el nostre grup per a la gran ascensió.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🚠 Vall de Núria: aventura a 2.000 metres (només en equip!)", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "L'activitat principal és l'ascensió a la ", "type": "text"}, {"text": "Vall de Núria", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", un indret idíl·lic a gairebé 2.000 metres d'altura, envoltat de cims que arriben als 3.000 metres. Aquesta vall és un dels paisatges més emblemàtics i bells de Catalunya. Aquí, el vostre grup podrà fer tota mena d' ", "type": "text"}, {"text": "esports d'aventura, senderisme i activitats de cohesió", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". A més de visitar l'històric Santuari de Núria, aquest entorn ens ofereix l'oportunitat perfecta per a l'exploració en equip.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🚂 Logística i ascens: el tren Cremallera", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Per pujar a la vall, farem servir el ", "type": "text"}, {"text": "tren Cremallera", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", ja que no es permet l'accés amb cotxe, cosa que garanteix una logística de transport organitzada i eficient per al nostre grup de 55 persones. Per als més aventurers, hi ha l'opció de pujar a peu des de Queralbs en una ruta d'unes 4 hores (nivell mitjà i 800 m de desnivell). ", "type": "text"}, {"text": "El bitllet del tren Cremallera i la pujada en telefèric dins de la Vall de Núria estan inclosos en el preu", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", perquè gaudiu de les vistes sense pagar res més.", "type": "text"}]}]}]}$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','ca','title',$j$"El Cor Salvatge del Pirineu: Aigüestortes i l'Estany de Sant Maurici"$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','ca','area',$j$"Pallars"$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','ca','meeting_point',$j$"Estació del Nord, C/ d'Alí Bei 80, 08013 Barcelona (Metro L1 Arc de Triomf). Arribeu 15 minuts abans."$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','ca','inclusions',$j$["Autocar d'anada i tornada des de Barcelona", "Guia acompanyant", "Taxi 4x4 Espot – Estany de Sant Maurici"]$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','ca','exclusions',$j$["Menjar i begudes"]$j$::jsonb),
('tour','62b03939-f84a-4a7a-908b-d2bb8dc4359d','ca','description',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🏞️ Aigüestortes: l'únic parc nacional de Catalunya", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "Tripcelona us convida a una aventura al cor dels Pirineus Centrals, al Parc Nacional d'Aigüestortes i Estany de Sant Maurici.", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Declarat Parc Nacional el 21 d'octubre de 1955, és l'únic parc nacional de Catalunya i un dels més emblemàtics d'Espanya. Ocupa més de 40.000 hectàrees a la província de Lleida, i abasta territoris entre l'Alta Ribagorça, el Pallars Sobirà, el Pallars Jussà i la Vall d'Aran.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "💧 La Famosa Ruta de les 'Aigües Tortes'", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "El nom del parc, ", "type": "text"}, {"text": "\"Aigüestortes\"", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", significa literalment ", "type": "text"}, {"text": "\"Aigües Tortes\"", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", en referència als nombrosos rius, rierols i canals que serpentegen per les seves valls creant paisatges únics. El parc és d'origen glacial i ofereix al vostre grup una experiència d'exploració incomparable, amb ", "type": "text"}, {"text": "més de 200 llacs (estanys)", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", densos boscos d'avets i faigs, i cims que superen els ", "type": "text"}, {"text": "3.000 metres", "type": "text", "marks": [{"type": "bold"}]}, {"text": ".", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "⛰️ Sant Maurici i Els Encantats: el símbol de l'expedició", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "El lloc més icònic del parc és l' ", "type": "text"}, {"text": "Estany de Sant Maurici", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". La bellesa de la badia es veu realçada per les majestuoses ", "type": "text"}, {"text": "Encantats", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", dues muntanyes bessones de forma punxeguda que dominen el paisatge i es troben a ", "type": "text"}, {"text": "1.910 metres d'altitud", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". En aquest entorn, organitzem rutes de senderisme i fotografia ideals per al ", "type": "text"}, {"text": "Team Building", "type": "text", "marks": [{"type": "bold"}]}, {"text": " i la immersió total a la natura salvatge del Pirineu.", "type": "text"}]}]}]}$j$::jsonb),
('tour','201a36a8-fbee-4737-b092-2e0dd669ce90','ca','title',$j$"El Canyó del Vero: Alquézar i la Ruta de les Passeres"$j$::jsonb),
