('tour','5132cb43-7103-49fd-b901-9fdc4ef49743','ca','description',$j${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "🏰 Rupit: la joia medieval del Collsacabra", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "La nostra exploració comença a ", "type": "text"}, {"text": "Rupit", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", un encantador poble medieval reconegut arreu del món (l'ONU Turisme el va incloure entre els «Best Tourism Villages», els millors pobles turístics del món). Caminant per Rupit, el vostre grup s'endinsarà en un entorn natural espectacular on el temps sembla haver-se aturat. És una experiència d'immersió cultural, amb els seus carrers estrets, cases de pedra i ponts penjants que conviden a l'exploració històrica. Rupit no és només un lloc, és un pas enrere en la història rural catalana.", "type": "text"}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "⛰️ Tavertet: el mirador geogràfic penjat", "type": "text", "marks": [{"type": "bold"}]}]}, {"type": "blockquote", "content": [{"type": "paragraph", "content": [{"text": "L'aventura assoleix el seu punt àlgid a ", "type": "text"}, {"text": "Tavertet", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", un impressionant poble situat dalt d'un ", "type": "text"}, {"text": "penyal natural (cingle)", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Aquest emplaçament geogràfic únic converteix Tavertet en un mirador inigualable. Des d'aquí, el vostre grup gaudirà de ", "type": "text"}, {"text": "vistes panoràmiques", "type": "text", "marks": [{"type": "bold"}]}, {"text": " sobre els vasts pantans de ", "type": "text"}, {"text": "Sau", "type": "text", "marks": [{"type": "bold"}]}, {"text": " i ", "type": "text"}, {"text": "Susqueda", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", i podrà contemplar la majestuositat de la serralada del ", "type": "text"}, {"text": "Montseny", "type": "text", "marks": [{"type": "bold"}]}, {"text": " a l'horitzó. Aquesta ubicació és ideal per reflexionar sobre la magnitud de la natura catalana i capturar fotografies impressionants de grup.", "type": "text"}]}]}]}$j$::jsonb),
